// =====================================
// RANISE IA PROFESSOR
// DYNAMIC CHAPTER RENDERER
// ONE ENGINE FOR ALL CHAPTERS
// NO CHAPTER-SPECIFIC FUNCTION
// NO ID CONFLICT
// =====================================

function renderChapterProfessorIA(chapterId){

    const campusContent =
        document.getElementById(
            "campusContent"
        );

    if(
        !campusContent ||
        !chapterId
    ){

        return;

    }


    const chapter =
        microsoftWordCourse.chapters.find(
            item =>
            item.id === chapterId
        );

    if(!chapter){

        return;

    }


    // =====================================
    // REMOVE ONLY THE PREVIOUS RANISE CARD
    // =====================================

    const oldIA =
        campusContent.querySelector(
            ".dynamic-ranise-professor-ia"
        );

    if(oldIA){

        oldIA.remove();

    }


    // =====================================
    // CREATE UNIQUE ID FROM CHAPTER ID
    // =====================================

    const safeChapterId =
        String(chapterId)
        .replace(/[^a-zA-Z0-9_-]/g,"_");


    const iaBox =
        document.createElement(
            "div"
        );


    iaBox.className =
        "dynamic-ranise-professor-ia";


    iaBox.id =
        "raniseProfessorIA_" +
        safeChapterId;


    // =====================================
    // RANISE CARD
    // =====================================

    iaBox.innerHTML = `

        <div class="chapter1-ia-card">

            <div class="chapter1-ia-topbar">

                <div class="chapter1-ia-title">

                    <span class="chapter1-ia-icon">
                        👩‍🏫
                    </span>

                    <div>

                        <h3>
                            Ranise MOISE
                        </h3>

                        <span>
                            Professeure IA
                        </span>

                    </div>

                </div>


                <button
                    type="button"
                    class="talk-to-ai-professor-btn"
                    data-ranise-chapter="${safeChapterId}"
                    aria-expanded="false"
                >

                    🎤 Talk

                </button>

            </div>


            <img
                src="ranise-moise-smile.png"
                alt="Ranise MOISE Professeure IA"
                class="chapter-professor-avatar"
            >


            <p class="chapter1-ia-role">

                Professeure CampusNumérique FOBAS

            </p>


            <p class="chapter1-ia-welcome">

                Bienvenue dans
                <strong>${chapter.title}</strong>.

                Je suis Ranise MOISE, votre Professeure IA.
                Je vais vous accompagner étape par étape
                tout au long de ce chapitre.

            </p>


            <div
                class="talk-to-ai-professor-panel"
                hidden
            >

                <div class="talk-ai-header">

                    <strong>
                        🎓 Talk to AI Professor
                    </strong>


                    <button
                        type="button"
                        class="talk-ai-close-btn"
                        aria-label="Close"
                    >

                        ✕

                    </button>

                </div>


                <div
                    class="talk-ai-conversation"
                    aria-live="polite"
                >

                    <div class="talk-ai-message professor-message">

                        <strong>
                            Professor:
                        </strong>

                        <span>

                            Bonjour, je suis Ranise MOISE,
                            votre Professeure IA CampusNumérique.

                            Bienvenue dans
                            ${chapter.title}.

                            Je vais vous accompagner
                            progressivement afin de vous aider
                            à comprendre chaque notion et
                            à réussir votre formation.

                        </span>

                    </div>

                </div>


                <div class="talk-ai-input-row">

                    <textarea
                        class="talk-ai-input"
                        rows="1"
                        placeholder="Type your question..."
                        autocomplete="off"
                    ></textarea>


                    <button
                        type="button"
                        class="talk-ai-send-btn"
                        aria-label="Send"
                    >

                        ➤

                    </button>

                </div>


                <div class="talk-ai-actions">

                    <button
                        type="button"
                        class="talk-ai-action-btn ranise-speak-btn"
                    >

                        🎤 Speak

                    </button>


                    <button
                        type="button"
                        class="talk-ai-action-btn ranise-voice-btn"
                    >

                        🔊 Professor

                    </button>

                </div>


                <div class="talk-ai-status">

                    Ready

                </div>

            </div>

        </div>

    `;


    // =====================================
    // PUT RANISE ABOVE THE CHAPTER CONTENT
    // =====================================

    campusContent.prepend(
        iaBox
    );


    // =====================================
    // LOCAL ELEMENTS ONLY
    // NO GLOBAL ID CONFLICT
    // =====================================

    const talkButton =
        iaBox.querySelector(
            ".talk-to-ai-professor-btn"
        );


    const closeButton =
        iaBox.querySelector(
            ".talk-ai-close-btn"
        );


    const panel =
        iaBox.querySelector(
            ".talk-to-ai-professor-panel"
        );


    const input =
        iaBox.querySelector(
            ".talk-ai-input"
        );


    const sendButton =
        iaBox.querySelector(
            ".talk-ai-send-btn"
        );


    const speakButton =
        iaBox.querySelector(
            ".ranise-speak-btn"
        );


    const voiceButton =
        iaBox.querySelector(
            ".ranise-voice-btn"
        );


    // =====================================
    // OPEN / CLOSE TALK PANEL
    // =====================================

    if(
        talkButton &&
        closeButton &&
        panel &&
        input
    ){

        talkButton.onclick =
            function(){

                const isOpen =
                    !panel.hidden;


                panel.hidden =
                    isOpen;


                talkButton.setAttribute(
                    "aria-expanded",
                    String(!isOpen)
                );


                if(!isOpen){

                    setTimeout(
                        function(){

                            input.focus();

                        },
                        100
                    );

                }

            };


        closeButton.onclick =
            function(){

                panel.hidden =
                    true;


                talkButton.setAttribute(
                    "aria-expanded",
                    "false"
                );

            };

    }


    // =====================================
    // SEND MESSAGE
    // REUSE EXISTING AI ENGINE
    // =====================================

    if(sendButton){

        sendButton.onclick =
            function(){

                const message =
                    input.value.trim();


                if(!message){

                    return;

                }


                window.campusLastProfessorResponse =
                    message;


                if(
                    typeof talkToAIProfessorSend ===
                    "function"
                ){

                    talkToAIProfessorSend();

                }

            };

    }


    // =====================================
    // ENTER TO SEND
    // =====================================

    if(input){

        input.addEventListener(
            "keydown",
            function(event){

                if(
                    event.key === "Enter" &&
                    !event.shiftKey
                ){

                    event.preventDefault();


                    if(sendButton){

                        sendButton.click();

                    }

                }

            }
        );

    }


    // =====================================
    // VOICE INPUT
    // =====================================

    if(speakButton){

        speakButton.onclick =
            function(){

                if(
                    typeof talkToAIProfessorStartListening ===
                    "function"
                ){

                    talkToAIProfessorStartListening();

                }

            };

    }


    // =====================================
    // MARYTTS PROFESSOR VOICE
    // =====================================

    if(voiceButton){

        voiceButton.onclick =
            async function(){

                const lastMessage =
                    window.campusLastProfessorResponse;


                if(
                    lastMessage &&
                    typeof speakProfessorIAWithMaryTTS ===
                    "function"
                ){

                    await speakProfessorIAWithMaryTTS(
                        lastMessage
                    );

                }

            };

    }

}




































// =====================================
// TALK TO AI PROFESSOR
// INITIALIZATION
// MARYTTS CAMILLE FRENCH VOICE COMPATIBLE
// =====================================

function initializeTalkToAIProfessor(){


    const talkButton =
        document.getElementById(
            "talkToAIProfessorBtn"
        );


    const closeButton =
        document.getElementById(
            "closeTalkToAIProfessorBtn"
        );


    const sendButton =
        document.getElementById(
            "talkAISendBtn"
        );


    const speakButton =
        document.getElementById(
            "talkAISpeakBtn"
        );


    const professorVoiceButton =
        document.getElementById(
            "talkAIProfessorVoiceBtn"
        );


    const input =
        document.getElementById(
            "talkAIProfessorInput"
        );



    if(
        !talkButton ||
        !closeButton ||
        !sendButton ||
        !input
    ){

        return;

    }



    talkButton.onclick = function(){


        const panel =
            document.getElementById(
                "talkToAIProfessorPanel"
            );


        if(!panel){

            return;

        }


        const isOpen =
            !panel.hidden;


        panel.hidden =
            isOpen;


        talkButton.setAttribute(
            "aria-expanded",
            String(!isOpen)
        );


        if(!isOpen){

            setTimeout(()=>{

                input.focus();

            },100);

        }

    };



    closeButton.onclick = function(){


        const panel =
            document.getElementById(
                "talkToAIProfessorPanel"
            );


        if(panel){

            panel.hidden = true;

        }


        talkButton.setAttribute(
            "aria-expanded",
            "false"
        );

    };



    sendButton.onclick = function(){

        talkToAIProfessorSend();

    };



    input.addEventListener(
        "keydown",
        function(event){

            if(
                event.key === "Enter" &&
                !event.shiftKey
            ){

                event.preventDefault();

                talkToAIProfessorSend();

            }

        }
    );



    if(speakButton){

        speakButton.onclick = function(){

            talkToAIProfessorStartListening();

        };

    }



    if(professorVoiceButton){

        professorVoiceButton.onclick =
            async function(){

                const lastProfessorMessage =
                    window.campusLastProfessorResponse;



                if(
                    lastProfessorMessage &&
                    typeof speakProfessorIAWithMaryTTS ===
                    "function"
                ){

                    await speakProfessorIAWithMaryTTS(
                        lastProfessorMessage
                    );

                }

            };

    }

}







// =====================================
// TALK TO AI PROFESSOR
// SEND TEXT
// =====================================

async function talkToAIProfessorSend(){


    const input =
        document.getElementById(
            "talkAIProfessorInput"
        );


    if(!input){

        return;

    }



    const message =
        input.value.trim();


    if(!message){

        return;

    }



    input.value = "";



    talkToAIProfessorAddMessage(
        "student",
        message
    );



    talkToAIProfessorSetStatus(
        "Professor is thinking..."
    );



    try{


        const response =
            await requestCampusAIProfessor(
                message
            );



        if(
            !response ||
            !response.trim()
        ){

            throw new Error(
                "EMPTY_AI_RESPONSE"
            );

        }



        window.campusLastProfessorResponse =
            response;



        talkToAIProfessorAddMessage(
            "professor",
            response
        );



        talkToAIProfessorSetStatus(
            "Professor ready"
        );




if(
    typeof speakProfessorIAWithMaryTTS ===
    "function"
){

    await speakProfessorIAWithMaryTTS(
        response
    );

}







    }catch(error){


        console.error(
            "Talk to AI Professor:",
            error
        );



const fallback =
    "Je suis prête à vous aider à apprendre Microsoft Word 2007. Veuillez vérifier que le service Professeur IA est connecté, puis posez votre question.";



        

        talkToAIProfessorAddMessage(
            "professor",
            fallback
        );


        talkToAIProfessorSetStatus(
            "AI connection unavailable"
        );

    }

}







// =====================================
// TALK TO AI PROFESSOR
// MESSAGE RENDERER
// =====================================

function talkToAIProfessorAddMessage(
    sender,
    message
){


    const conversation =
        document.getElementById(
            "talkAIConversation"
        );


    if(!conversation){

        return;

    }



    const messageBox =
        document.createElement(
            "div"
        );


    messageBox.className =
        sender === "student"
        ? "talk-ai-message student-message"
        : "talk-ai-message professor-message";



    const label =
        sender === "student"
        ? "You:"
        : "Professor:";



    const strong =
        document.createElement(
            "strong"
        );


    strong.textContent =
        label;



    const text =
        document.createElement(
            "span"
        );


    text.textContent =
        message;



    messageBox.appendChild(
        strong
    );


    messageBox.appendChild(
        text
    );



    conversation.appendChild(
        messageBox
    );



    conversation.scrollTop =
        conversation.scrollHeight;

}







// =====================================
// TALK TO AI PROFESSOR
// STATUS
// =====================================

function talkToAIProfessorSetStatus(
    message
){


    const status =
        document.getElementById(
            "talkAIStatus"
        );


    if(status){

        status.textContent =
            message;

    }

}







// =====================================
// TALK TO AI PROFESSOR
// MICROPHONE / SPEECH TO TEXT
// =====================================

let campusProfessorRecognition = null;



function talkToAIProfessorStartListening(){


    const input =
        document.getElementById(
            "talkAIProfessorInput"
        );


    const speakButton =
        document.getElementById(
            "talkAISpeakBtn"
        );


    if(!input){

        return;

    }



    const SpeechRecognition =
        window.SpeechRecognition ||
        window.webkitSpeechRecognition;



    if(!SpeechRecognition){

        talkToAIProfessorSetStatus(
            "Speech recognition is not supported on this browser."
        );

        return;

    }



    if(campusProfessorRecognition){

        try{

            campusProfessorRecognition.stop();

        }catch(error){}

    }



    campusProfessorRecognition =
        new SpeechRecognition();



    campusProfessorRecognition.lang =
        "fr-FR";


    campusProfessorRecognition.continuous =
        false;


    campusProfessorRecognition.interimResults =
        false;


    campusProfessorRecognition.maxAlternatives =
        1;



    if(speakButton){

        speakButton.textContent =
            "🎤 Listening...";

    }



    talkToAIProfessorSetStatus(
        "Listening..."
    );



    campusProfessorRecognition.onresult =
        function(event){


            const transcript =
                event.results[0][0].transcript;


            input.value =
                transcript;



            talkToAIProfessorSetStatus(
                "Message received"
            );


        };



    campusProfessorRecognition.onerror =
        function(event){


            talkToAIProfessorSetStatus(
                "Microphone error: " +
                event.error
            );


        };



    campusProfessorRecognition.onend =
        function(){


            if(speakButton){

                speakButton.textContent =
                    "🎤 Speak";

            }


        };



    try{

        campusProfessorRecognition.start();

    }catch(error){

        talkToAIProfessorSetStatus(
            "Microphone could not start."
        );

    }

}







// =====================================
// CAMPUS AI PROFESSOR
// FOBAS GROQ BRIDGE
// =====================================

window.CampusAIProfessor = {

    async ask(data) {

        const response = await fetch(
            'https://api.fondationbackupspirituel.com/api/ai-professor',
            {

                method: 'POST',

                headers: {

                    'Content-Type':
                        'application/json'

                },

                body: JSON.stringify({

                    message:
                        data.message,

                    course:
                        data.course,

                    chapter:
                        data.chapter,

                    language:
                        data.language

                })

            }
        );


        const result =
            await response.json();


        if (!response.ok) {

            throw new Error(

                result.error ||
                'AI Professor request failed.'

            );

        }


        return result.text;

    }

};




















// =====================================
// CAMPUS AI PROFESSOR
// REQUEST BRIDGE
// CONNECTS TALK UI TO GROQ BRIDGE
// ISOLATED MODULE
// =====================================

async function requestCampusAIProfessor(message){

    if(
        !message ||
        typeof message !== "string" ||
        !message.trim()
    ){

        throw new Error(
            "AI_MESSAGE_EMPTY"
        );

    }


    if(
        !window.CampusAIProfessor ||
        typeof window.CampusAIProfessor.ask !== "function"
    ){

        throw new Error(
            "CAMPUS_AI_PROFESSOR_BRIDGE_NOT_AVAILABLE"
        );

    }


    const response =
        await window.CampusAIProfessor.ask({

            message:
                message.trim(),

            course:
                "Microsoft Word 2007",

            chapter:
                "Chapitre 1",

            language:
                "fr-FR"

        });


    if(
        !response ||
        typeof response !== "string" ||
        !response.trim()
    ){

        throw new Error(
            "AI_EMPTY_RESPONSE"
        );

    }


    return response.trim();

}








































// =====================================
// CAMPUS AI PROFESSOR
// MARYTTS CAMILLE FRENCH VOICE BRIDGE
// CONNECTS GROQ TEXT TO MARYTTS
// FULLY COMPATIBLE WITH
// /api/ranise/voice
// =====================================

let raniseProfessorAudio = null;



async function speakProfessorIAWithMaryTTS(text){

    console.log(
        "=== MARYTTS FRONTEND START ==="
    );


    if(
        !text ||
        typeof text !== "string" ||
        !text.trim()
    ){

        console.error(
            "MARYTTS ERROR: EMPTY TEXT"
        );

        return;

    }



    try{

        console.log(
            "MARYTTS: SENDING TEXT TO BACKEND"
        );



        const response =
            await fetch(

                "https://api.fondationbackupspirituel.com/api/ranise/voice",

                {

                    method:"POST",

                    headers:{

                        "Content-Type":
                            "application/json"

                    },

                    body:
                        JSON.stringify({

                            text:
                                text.trim()

                        })

                }
            );



        console.log(

            "MARYTTS RESPONSE:",

            response.status

        );



        if(!response.ok){

            const errorText =
                await response.text();

            console.error(
                "MARYTTS BACKEND ERROR:",
                errorText
            );

            throw new Error(
                "MARYTTS_REQUEST_FAILED"
            );

        }



        const result =
            await response.json();



        if(

            !result ||
            typeof result.audio !== "string" ||
            !result.audio

        ){

            throw new Error(
                "MARYTTS_AUDIO_MISSING"
            );

        }



        const mimeType =
            result.mimeType ||
            "audio/wav";



        const binaryString =
            atob(
                result.audio
            );



        const bytes =
            new Uint8Array(
                binaryString.length
            );



        for(

            let i = 0;

            i < binaryString.length;

            i++

        ){

            bytes[i] =
                binaryString.charCodeAt(i);

        }



        const audioBlob =
            new Blob(

                [bytes],

                {

                    type:
                        mimeType

                }

            );



        const audioUrl =
            URL.createObjectURL(
                audioBlob
            );



        if(
            raniseProfessorAudio
        ){

            try{

                raniseProfessorAudio.pause();

                raniseProfessorAudio.currentTime =
                    0;

            }catch(error){}

        }



        raniseProfessorAudio =
            new Audio(
                audioUrl
            );



        raniseProfessorAudio.volume = 1;



        // =====================================
        // WAIT FOR REAL AUDIO PLAYBACK
        // =====================================

        await new Promise(
            function(resolve, reject){

                let finished =
                    false;



                function cleanup(){

                    if(
                        raniseProfessorAudio
                    ){

                        raniseProfessorAudio.onplay =
                            null;

                        raniseProfessorAudio.onended =
                            null;

                        raniseProfessorAudio.onerror =
                            null;

                    }

                }



                function finishSuccess(){

                    if(finished){

                        return;

                    }



                    finished =
                        true;



                    cleanup();



                    if(

                        typeof raniseStopTalking ===
                        "function"

                    ){

                        raniseStopTalking();

                    }



                    try{

                        URL.revokeObjectURL(
                            audioUrl
                        );

                    }catch(error){}



                    resolve();

                }



                function finishError(error){

                    if(finished){

                        return;

                    }



                    finished =
                        true;



                    cleanup();



                    if(

                        typeof raniseStopTalking ===
                        "function"

                    ){

                        raniseStopTalking();

                    }



                    try{

                        URL.revokeObjectURL(
                            audioUrl
                        );

                    }catch(error){}



                    reject(error);

                }



                raniseProfessorAudio.onplay =
                    function(){

                        console.log(
                            "MARYTTS AUDIO PLAYING"
                        );



                        if(

                            typeof raniseStartTalking ===
                            "function"

                        ){

                            raniseStartTalking();

                        }

                    };



                // =====================================
                // CRITICAL:
                // PROMISE RESOLVES ONLY WHEN
                // THE COMPLETE AUDIO HAS ENDED
                // =====================================

                raniseProfessorAudio.onended =
                    function(){

                        console.log(
                            "MARYTTS AUDIO ENDED"
                        );



                        finishSuccess();

                    };



                raniseProfessorAudio.onerror =
                    function(){

                        console.error(
                            "MARYTTS AUDIO ERROR"
                        );



                        finishError(
                            new Error(
                                "MARYTTS_AUDIO_PLAYBACK_ERROR"
                            )
                        );

                    };



                let playPromise;



                try{

                    playPromise =
                        raniseProfessorAudio.play();

                }catch(playError){

                    finishError(
                        playError
                    );

                    return;

                }



                if(

                    playPromise &&
                    typeof playPromise.catch ===
                    "function"

                ){

                    playPromise.catch(
                        function(playError){

                            finishError(
                                playError
                            );

                        }
                    );

                }

            }
        );



        console.log(
            "=== MARYTTS AUDIO COMPLETELY FINISHED ==="
        );



    }catch(error){

        console.error(
            "MARYTTS FRONTEND ERROR:",
            error
        );



        if(

            typeof raniseStopTalking ===
            "function"

        ){

            raniseStopTalking();

        }



        if(

            typeof talkToAIProfessorSetStatus ===
            "function"

        ){

            talkToAIProfessorSetStatus(

                "French voice unavailable."

            );

        }

    }

}































// =====================================
// RANISE MOISE
// FRENCH VOICE ENGINE
// =====================================

function speakProfessorIA(message){

    if(!window.speechSynthesis){
        return;
    }

    const speechEngine = window.speechSynthesis;

    speechEngine.cancel();

    const speech = new SpeechSynthesisUtterance();

    speech.text = message;
    speech.lang = "fr-FR";
    speech.rate = 1;
    speech.pitch = 1;
    speech.volume = 1;

    function speakNow(){

        const voices = speechEngine.getVoices();

        const voice = voices.find(v=>v.lang && v.lang.startsWith("fr"));


if(voice){
    speech.voice = voice;
}



speech.onstart = ()=>{

    raniseStartTalking();

};



raniseStartTalking();

speech.onend = ()=>{

    raniseStopTalking();

};


speech.onerror = ()=>{

    raniseStopTalking();

};


speechEngine.speak(speech);





    }



    if(speechEngine.getVoices().length > 0){

        setTimeout(speakNow,150);

    }else{

        speechEngine.onvoiceschanged = ()=>{

            setTimeout(speakNow,150);

        };

    }

}





// =====================================
// RANISE MOISE AVATAR TALKING ENGINE
// =====================================

let raniseTalkingTimer = null;

function raniseStartTalking(){



const img = document.getElementById(
    "chapterProfessorAvatar"
);


 

    if(!img){
        return;
    }


    let speaking = false;


    clearInterval(raniseTalkingTimer);


    raniseTalkingTimer = setInterval(()=>{


        speaking = !speaking;


        if(speaking){

            img.src = "ranise-moise-speaking-smile.png";

        }else{

            img.src = "ranise-moise-smile.png";

        }


    },300);


}



function raniseStopTalking(){

    clearInterval(raniseTalkingTimer);



const img = document.getElementById(
    "chapterProfessorAvatar"
);






    if(img){

        img.src = "ranise-moise-smile.png";

    }

}







































// =====================================
// RANISE MOISE IA PROFESSOR
// PEDAGOGICAL ENGINE
// BLOCK 1 - COURSE READER
// READ-ONLY / ISOLATED
// MICROSOFT WORD 2007 - CHAPITRE 1
// =====================================


const RaniseMoisePedagogicalEngine = {


    // =====================================
    // GET CHAPTER
    // READ ONLY
    // =====================================

    getChapter:function(chapterId){


        if(
            typeof microsoftWordCourse ===
            "undefined"
        ){

            return null;

        }



        if(
            !microsoftWordCourse.chapters ||
            !Array.isArray(
                microsoftWordCourse.chapters
            )
        ){

            return null;

        }



        return microsoftWordCourse.chapters.find(

            chapter =>

            chapter.id === chapterId

        ) || null;


    },





    // =====================================
    // GET CHAPTER 1
    // =====================================

    getChapter1:function(){


        return this.getChapter(
            "chapitre1"
        );


    },





    // =====================================
    // VERIFY CHAPTER STRUCTURE
    // READ ONLY
    // =====================================

    verifyChapter:function(chapter){


        if(!chapter){

            return false;

        }



        if(
            typeof chapter.id !==
            "string"
        ){

            return false;

        }



        if(
            typeof chapter.title !==
            "string"
        ){

            return false;

        }



        if(
            !Array.isArray(
                chapter.theory
            )
        ){

            return false;

        }



        if(
            !Array.isArray(
                chapter.practice
            )
        ){

            return false;

        }



        if(
            !Array.isArray(
                chapter.exercises
            )
        ){

            return false;

        }



        if(
            typeof chapter.homework !==
            "string"
        ){

            return false;

        }



        if(
            !Array.isArray(
                chapter.evaluation
            )
        ){

            return false;

        }



        if(
            !Array.isArray(
                chapter.objective
            )
        ){

            return false;

        }



        return true;


    },





    // =====================================
    // READ CHAPTER 1 PEDAGOGICAL DATA
    // READ ONLY
    // =====================================

    readChapter1:function(){


        const chapter =
            this.getChapter1();



        if(
            !this.verifyChapter(
                chapter
            )
        ){

            return null;

        }



        return {

            id:
                chapter.id,

            title:
                chapter.title,

            theory:
                chapter.theory,

            practice:
                chapter.practice,

            exercises:
                chapter.exercises,

            homework:
                chapter.homework,

            evaluation:
                chapter.evaluation,

            objective:
                chapter.objective

        };


    },


};





